hero.styles:
.techzen-hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  background: var(--color-bg-primary);
  overflow: hidden;
}

.hero-background {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: -2;
}

.hero-gradient-overlay {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: var(--gradient-primary);
  opacity: 0.1;
}

.hero-geometric-shapes {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

.shape {
  position: absolute;
  border-radius: 50%;
  background: var(--gradient-primary);
  opacity: 0.1;
  animation: float 6s ease-in-out infinite;
}

.shape-1 {
  width: 200px;
  height: 200px;
  top: 20%;
  left: 10%;
  animation-delay: 0s;
}

.shape-2 {
  width: 150px;
  height: 150px;
  top: 60%;
  right: 15%;
  animation-delay: 2s;
}

.shape-3 {
  width: 100px;
  height: 100px;
  bottom: 20%;
  left: 20%;
  animation-delay: 4s;
}

@keyframes float {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  50% { transform: translateY(-20px) rotate(180deg); }
}

.hero-content {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--spacing-16);
  align-items: center;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-6);
  z-index: 1;
  position: relative;
}

.hero-title {
  font-family: var(--font-display);
  font-size: var(--font-size-7xl);
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: var(--spacing-6);
}

.title-line-1,
.title-line-2 {
  display: block;
  color: var(--color-fg-primary);
}

.title-line-3 {
  display: block;
  background: var(--gradient-primary);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero-description {
  font-size: var(--font-size-xl);
  color: var(--color-fg-secondary);
  line-height: 1.6;
  margin-bottom: var(--spacing-8);
  max-width: 500px;
}

.hero-cta {
  display: flex;
  gap: var(--spacing-4);
}

.glass-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  padding: var(--spacing-4) var(--spacing-8);
  background: var(--glass-bg);
  backdrop-filter: var(--glass-backdrop);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-lg);
  color: var(--color-fg-primary);
  text-decoration: none;
  font-weight: 600;
  font-size: var(--font-size-lg);
  transition: all var(--duration-normal) var(--ease-out);
  overflow: hidden;
}

.glass-button:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-glow);
  border-color: var(--color-accent-purple);
}

.button-shine {
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);
  animation: shine 3s ease-in-out infinite;
}

@keyframes shine {
  0% { left: -100%; }
  50% { left: 100%; }
  100% { left: 100%; }
}

.hero-visual {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-8);
}

.hero-devices {
  display: flex;
  gap: var(--spacing-6);
  justify-content: center;
}

.device {
  width: 200px;
  height: 300px;
  background: var(--color-bg-secondary);
  border-radius: var(--radius-xl);
  padding: var(--spacing-4);
  box-shadow: var(--shadow-lg);
  transition: all var(--duration-normal) var(--ease-out);
}

.device:hover {
  transform: translateY(-10px) rotate(5deg);
  box-shadow: var(--shadow-glow-lg);
}

.device-screen {
  width: 100%;
  height: 100%;
  background: var(--color-bg-primary);
  border-radius: var(--radius-lg);
  padding: var(--spacing-4);
  display: flex;
  align-items: center;
  justify-content: center;
}

.screen-content {
  text-align: center;
  color: var(--color-fg-primary);
}

.ai-visualization {
  position: relative;
  width: 80px;
  height: 80px;
}

.ai-node {
  position: absolute;
  width: 20px;
  height: 20px;
  background: var(--color-accent-purple);
  border-radius: 50%;
  animation: pulse 2s ease-in-out infinite;
}

.ai-connection {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 40px;
  height: 2px;
  background: var(--color-accent-blue);
  transform: translate(-50%, -50%) rotate(45deg);
  animation: pulse 2s ease-in-out infinite reverse;
}

@keyframes pulse {
  0%, 100% { opacity: 0.5; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.2); }
}

.hero-counter {
  text-align: center;
  padding: var(--spacing-6);
  background: var(--glass-bg);
  backdrop-filter: var(--glass-backdrop);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-xl);
}

.counter-display {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-2);
}

.counter-number {
  font-size: var(--font-size-5xl);
  font-weight: 800;
  color: var(--color-fg-primary);
  font-family: var(--font-display);
}

.counter-text {
  font-size: var(--font-size-sm);
  color: var(--color-fg-secondary);
  font-weight: 500;
}

serviceCard.styles:
.techzen-service-card {
  background: var(--color-bg-secondary);
  border: 1px solid var(--glass-border);
  border-radius: var(--radius-2xl);
  padding: var(--spacing-8);
  transition: all var(--duration-normal) var(--ease-out);
  position: relative;
  overflow: hidden;
}

.techzen-service-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--shadow-glow);
  border-color: var(--color-accent-purple);
}

.techzen-service-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--gradient-primary);
  opacity: 0;
  transition: opacity var(--duration-normal) var(--ease-out);
  z-index: -1;
}

.techzen-service-card:hover::before {
  opacity: 0.05;
}

.service-icon-container {
  margin-bottom: var(--spacing-6);
}

.service-icon {
  width: 64px;
  height: 64px;
  background: var(--gradient-primary);
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-fg-primary);
  box-shadow: var(--shadow-glow);
}

.service-title {
  font-size: var(--font-size-2xl);
  font-weight: 700;
  color: var(--color-fg-primary);
  margin-bottom: var(--spacing-4);
  font-family: var(--font-display);
}

.service-description {
  color: var(--color-fg-secondary);
  line-height: 1.6;
  margin-bottom: var(--spacing-6);
}

.service-image {
  margin-top: var(--spacing-6);
}

.service-visual {
  width: 100%;
  height: 120px;
  background: var(--color-bg-primary);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.visual-element {
  width: 60px;
  height: 60px;
  background: var(--gradient-primary);
  border-radius: 50%;
  animation: pulse 3s ease-in-out infinite;
}
